"""Self-contained beginner UI for the local LAND-DATA dashboard."""
import json


def render_dashboard_html(csrf: str) -> bytes:
    page = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>LAND-DATA 采集与审核</title>
<style>
:root{--ink:#172033;--muted:#64748b;--line:#dbe2ea;--bg:#f3f5f7;--surface:#fff;--accent:#2456d6;--accent2:#e8efff;--ok:#166534;--okbg:#ecfdf3;--warn:#92400e;--warnbg:#fff7ed;--danger:#b42318;--dangerbg:#fef3f2;--radius:14px;--shadow:0 8px 24px rgba(15,23,42,.07)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"PingFang SC","Noto Sans SC",sans-serif}::selection{background:#cbdcff;color:#10214d}
button,input,select,textarea{font:inherit}button,input,select,textarea{border-radius:9px;border:1px solid var(--line)}button{border:0;background:var(--accent);color:#fff;padding:10px 15px;font-weight:650;cursor:pointer;transition:background .18s ease,transform .18s ease}button:hover{background:#1947bc}button:active{transform:translateY(1px)}button:disabled{opacity:.46;cursor:not-allowed}.secondary{background:#eef2f7!important;color:#334155!important}.danger{background:var(--danger)!important}.linkbtn{background:transparent!important;color:var(--accent)!important;padding:4px 6px}.small{font-size:13px;padding:7px 10px}:focus-visible{outline:3px solid rgba(36,86,214,.3);outline-offset:2px}
header{background:var(--ink);color:white;padding:22px 24px 18px}header .wrap{max-width:1440px;margin:auto}h1{font-size:22px;margin:0 0 4px;letter-spacing:-.02em}header p{margin:0;color:#cbd5e1}.steps{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:18px}.step{display:flex;gap:9px;align-items:center;padding:9px 11px;border-radius:10px;background:rgba(255,255,255,.08);color:#dbe6ff;font-size:13px}.step b{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:white;color:var(--ink);font-variant-numeric:tabular-nums}
main{max-width:1440px;margin:auto;padding:18px;display:grid;gap:16px}.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:20px;box-shadow:var(--shadow)}.panel h2{font-size:19px;margin:0 0 4px;letter-spacing:-.01em}.lead{color:var(--muted);margin:0 0 18px}.welcome{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;background:#eef3ff;border:1px solid #cddcff}.welcome h2{font-size:20px}.welcome ol{margin:10px 0 0;padding-left:20px}.welcome li{margin:4px 0}.hidden{display:none!important}
.flow-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(340px,.85fr);gap:16px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.field{display:grid;gap:5px}.field label{font-size:13px;font-weight:650}.hint{font-size:12px;color:var(--muted)}input,select,textarea{width:100%;padding:10px 11px;background:#fff;color:var(--ink)}textarea{min-height:82px;resize:vertical}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.callout{padding:12px 14px;border-radius:10px;background:var(--warnbg);color:#7c3f12;border:1px solid #fed7aa}.success{background:var(--okbg);color:var(--ok);border-color:#bbf7d0}.error{background:var(--dangerbg);color:var(--danger);border-color:#fecaca}.job-explain{margin:13px 0;padding:14px;background:#f8fafc;border:1px solid var(--line);border-radius:10px}.job-explain b{display:block;margin-bottom:3px}.facts{display:flex;flex-wrap:wrap;gap:7px;margin-top:9px}.tag{display:inline-flex;padding:3px 8px;border-radius:999px;background:#e8edf4;color:#334155;font-size:12px}.tag.llm{background:#fff1d6;color:#7c4a03}.tag.zero{background:#dcfce7;color:#166534}details{margin-top:14px;border-top:1px solid var(--line);padding-top:11px}summary{cursor:pointer;font-weight:650;color:#475569}
.source-grid,.storage-grid,.job-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}.source,.storage,.job{padding:13px;border:1px solid var(--line);border-radius:11px;background:#fbfcfe}.source h4,.storage h4,.job h4{margin:0 0 5px;font-size:14px}.source p,.storage p,.job p{margin:3px 0;color:var(--muted);font-size:12px}.path{word-break:break-all;color:#334155!important}.progress{height:8px;border-radius:999px;background:#e5eaf0;overflow:hidden;margin:10px 0}.progress>span{display:block;height:100%;background:var(--accent)}.status{font-weight:700}.status.SUCCEEDED,.status.COMPLETE,.status.NOT_NEEDED{color:var(--ok)}.status.FAILED,.status.RETRY_REQUIRED{color:var(--danger)}
.review-layout{display:grid;grid-template-columns:minmax(520px,1fr) minmax(360px,.75fr);gap:16px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.toolbar input{flex:1;min-width:180px}.toolbar select{width:auto}.count{font-size:13px;color:var(--muted);margin-bottom:8px}.tablewrap{overflow:auto;max-height:680px;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid #e8edf3;vertical-align:top}th{position:sticky;top:0;background:#f8fafc;color:#475569;z-index:1}.item{cursor:pointer}.item:hover{background:#f1f6ff}.pill{display:inline-block;padding:2px 6px;border-radius:999px;background:#e8edf4;font-size:10px}.check-cell{width:74px;text-align:center}.llm-check{width:18px;height:18px;accent-color:var(--accent);cursor:pointer}.disabled-choice{font-size:11px;color:var(--muted);white-space:nowrap}.llm-panel{margin:14px 0;padding:14px;background:#f8fafc;border:1px solid var(--line);border-radius:11px}.llm-panel h3{margin:0 0 4px;font-size:16px}.llm-controls{display:grid;grid-template-columns:minmax(180px,1.4fr) minmax(120px,.6fr);gap:12px;margin-top:12px}.llm-budget{margin:12px 0 0;font-weight:650;color:#334155}.detail-empty{padding:32px 10px;text-align:center;color:var(--muted)}.detail-section{padding:12px 0;border-top:1px solid var(--line)}.detail-section:first-child{border:0}.pre{white-space:pre-wrap;word-break:break-word;background:#f8fafc;padding:11px;border-radius:9px;max-height:330px;overflow:auto;font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace}.result{margin-top:12px}.empty{padding:28px;text-align:center;background:#f8fafc;border-radius:10px;color:var(--muted)}
.publish-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.preflight-list{display:grid;gap:8px;margin:10px 0}.preflight-item{padding:10px;border:1px solid var(--line);border-radius:9px;background:#fff}.preflight-item.blocked{border-color:#fecaca;background:#fff7f7}.preflight-item.ready{border-color:#bbf7d0;background:#f4fff7}.blocker{font-size:12px;padding:3px 0;color:var(--danger)}.homepage-card{margin-top:12px}.homepage-card .task-path{word-break:break-all;font:12px/1.5 ui-monospace,SFMono-Regular,Menlo,monospace;color:#334155}.footer-note{font-size:12px;color:var(--muted);margin-top:14px}.raw-toggle pre{margin-top:8px}
@media(max-width:900px){.steps{grid-template-columns:repeat(2,1fr)}.flow-grid,.review-layout{grid-template-columns:1fr}.field-grid,.publish-grid,.llm-controls{grid-template-columns:1fr}.panel{padding:16px}.tablewrap{max-height:520px}}
@media(max-width:560px){header{padding:18px 15px}.steps{grid-template-columns:1fr 1fr}.step{display:block}.step b{margin-bottom:4px}main{padding:10px}.welcome{display:block}.welcome button{margin-top:12px}.toolbar>*{width:100%!important}.actions button{flex:1}.tablewrap{border:0}table,thead,tbody,tr,th,td{display:block}thead{display:none}tr{border:1px solid var(--line);border-radius:10px;margin:8px 0;padding:8px}td{border:0;padding:4px}.item td:nth-child(4),.item td:nth-child(5){font-size:12px;color:var(--muted)}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body>
<header><div class="wrap"><h1>LAND-DATA 采集与审核</h1><p>从选择城市到发布内容，每一步都有说明；默认不会调用千问。</p><nav class="steps" aria-label="工作流程"><a class="step" href="#collect"><b>1</b><span>选择城市<br>规划来源</span></a><a class="step" href="#run"><b>2</b><span>采集处理<br>查看进度</span></a><a class="step" href="#review"><b>3</b><span>查看数据<br>处理审核</span></a><a class="step" href="#publish"><b>4</b><span>核对差异<br>发布 LAND</span></a></nav></div></header>
<main>
<section id="welcome" class="panel welcome"><div><h2>第一次使用？先完成一次零模型采集</h2><p class="lead">大约需要三步：输入城市、查看采集计划、启动规则处理。采集到的数据会留在本机。</p><ol><li>先创建或选择城市。</li><li>查看哪些来源已配置、哪些还缺范围。</li><li>先运行“零模型规则处理”，需要时再挑选少量内容交给千问。</li></ol></div><button id="dismiss-welcome" class="secondary">我知道了</button></section>

<section id="collect" class="panel"><h2>1. 选择城市并查看采集计划</h2><p class="lead">新城市会自动建立城市档案和搜索词库。结构化来源需要单独配置，系统不会猜测。</p><div class="flow-grid"><div><div class="field-grid"><div class="field"><label for="wf-city">城市 ID</label><input id="wf-city" placeholder="例如 san-francisco" autocomplete="off"><span class="hint">小写英文和连字符；以后更新同一城市时继续使用它。</span></div><div class="field"><label for="wf-city-name">城市名称</label><input id="wf-city-name" placeholder="例如 San Francisco"><span class="hint">用于生成中文搜索词和城市定位。</span></div><div class="field"><label for="wf-country">国家代码</label><input id="wf-country" value="US" maxlength="2"><span class="hint">两位代码，例如 US、JP、FR。</span></div><div class="field"><label for="wf-reviewer">操作者</label><input id="wf-reviewer" placeholder="你的名字"><span class="hint">写入审计记录，方便以后知道是谁启动的。</span></div></div><div class="field" style="margin-top:12px"><label for="wf-reason">本次原因</label><input id="wf-reason" placeholder="例如：第一次采集旧金山"><span class="hint">创建城市、启动和取消作业都需要原因。</span></div><div class="actions"><button id="create-city">创建 / 补全城市</button><button id="load-plan" class="secondary">查看采集计划</button></div><div id="wf-message" class="result"></div><div id="homepage-action" class="homepage-card" aria-live="polite"></div></div><div><h3>来源计划</h3><div id="wf-plan" class="source-grid"><div class="empty">输入城市 ID 后点击“查看采集计划”。</div></div><details class="raw-toggle"><summary>查看原始计划数据</summary><pre id="wf-plan-raw" class="pre"></pre></details></div></div></section>

<section id="run" class="panel"><h2>2. 启动采集或处理</h2><p class="lead">一次只做一个明确步骤。长任务在后台运行，离开页面后记录仍会保留。</p><div class="flow-grid"><div><div class="field"><label for="wf-step">你想做什么？</label><select id="wf-step"><option value="xhs_collect">从小红书采集新内容</option><option value="threads_collect">从 Threads 搜集公开帖子</option><option value="xhs_process">整理已采集内容（推荐先选）</option><option value="multi_collect">运行官方 / OSM 结构化来源</option><option value="land_raw_process">处理 LAND Raw 文件</option><option value="publish_prepare">准备知识发布包</option><option value="knowledge_extract">用千问整理选中的候选</option></select></div><div id="job-explain" class="job-explain"></div><div id="threads-fields" class="field-grid" style="display:none;margin:12px 0"><div class="field"><label for="wf-threads-query">Threads 搜索词</label><input id="wf-threads-query" placeholder="例如 Hanoi cafe"><span class="hint">会搜索公开帖子；关键词不会自动限制城市。</span></div><div class="field"><label for="wf-threads-search-type">结果排序</label><select id="wf-threads-search-type"><option value="RECENT">最新</option><option value="TOP">热门</option></select></div><div class="field"><label for="wf-threads-limit">最多帖子数</label><input id="wf-threads-limit" type="number" min="1" max="5" value="5"><span class="hint">官方 API 单次最多保存 5 篇。</span></div></div><details><summary>高级选项</summary><div class="field-grid" style="margin-top:12px"><div class="field"><label for="wf-sources">结构化来源</label><input id="wf-sources" placeholder="例如 osm,nyc-parks-events"><span class="hint">只对“官方 / OSM”步骤生效；留空运行该城市全部已配置来源。</span></div><div class="field"><label for="wf-model">千问模型</label><input id="wf-model" value="qwen3.7-flash"><span class="hint">只对千问步骤生效。</span></div><div class="field"><label for="wf-limit">千问调用上限</label><input id="wf-limit" type="number" min="1" max="100" value="1"><span class="hint">选中多少条，就设置多少；系统不会超过这个数量。</span></div></div><div class="field" style="margin-top:12px"><label for="wf-candidates">候选 ID</label><textarea id="wf-candidates" placeholder="只在千问步骤填写；一行一个或用逗号分隔"></textarea></div></details><div class="actions"><button id="start-job">启动这个步骤</button><button id="refresh-workflow" class="secondary">刷新进度</button></div><div id="wf-result" class="result"></div></div><div><h3>作业进度</h3><div id="wf-jobs" class="job-grid"><div class="empty">还没有作业。先从左侧选择一个步骤。</div></div><h3 style="margin-top:18px">数据保存在哪里</h3><div id="storage" class="storage-grid"></div><details class="raw-toggle"><summary>查看运行原始数据</summary><pre id="runtime" class="pre"></pre></details></div></div></section>

<section id="review" class="panel"><h2>3. 查看数据并处理审核</h2><p class="lead">本地 classifier 先用零模型规则分流，并显示分类、置信度和原因。官方结构化数据满足安全门槛时会自动通过；社区经验、冲突或证据不足的内容进入待审核列表。</p><div class="callout success"><b>你不必逐条人工查看</b><br>可以直接在 Codex 对话中让我核对待审核证据并记录决定，全程不调用千问。证据不足的内容会被拒绝或继续阻断，不会直接发布。</div><div class="llm-panel" aria-labelledby="llm-review-title"><h3 id="llm-review-title">可选：用千问辅助整理少量候选</h3><p class="hint">默认是 0 次模型调用。只有“知识候选”且状态为“需要审核”的内容可以勾选；地点、活动、官方指引和已经生成的草稿不能从这里调用。模型只生成 <code>DRAFT_NEEDS_REVIEW</code> 草稿，绝不会自动通过或发布。</p><div class="llm-controls"><div class="field"><label for="review-llm-model">模型名称</label><input id="review-llm-model" value="qwen3.7-flash" autocomplete="off"><span class="hint">使用你已配置的 Qwen 模型；未配置密钥时作业会明确失败。</span></div><div class="field"><label for="review-llm-limit">最大调用次数</label><input id="review-llm-limit" type="number" min="1" max="100" value="1"><span class="hint">建议等于已选数量；系统不会超过这个上限。</span></div></div><div class="actions"><button id="llm-select-first" class="secondary" type="button">选择当前列表前 N 条</button><button id="llm-clear-selection" class="secondary" type="button">清空选择</button><label class="field" style="display:flex;flex-direction:row;align-items:center;gap:7px;margin-left:auto"><span>选择数量 N</span><input id="llm-pick-count" type="number" min="1" max="100" value="1" style="width:90px"></label></div><p id="llm-budget" class="llm-budget" role="status" aria-live="polite">已选 0 条，预计最多调用 0 次。还没有启动模型作业。</p><div id="llm-review-message" class="result" aria-live="polite"></div><div class="actions"><button id="start-llm-review" type="button" disabled>对已选内容启动模型辅助审核</button></div></div><div class="review-layout"><div><div class="toolbar"><input id="q" placeholder="搜索标题、城市或 ID"><select id="bucket"><option value="REVIEW_REQUIRED" selected>只看需要审核</option><option value="">全部状态</option><option value="AUTO_ACCEPTED">自动通过 / 信息</option><option value="REVIEWED_ACCEPTED">已审核通过</option><option value="REVIEWED_REJECTED">已审核拒绝</option><option value="FAILED_OR_BLOCKED">失败 / 阻塞</option><option value="PUBLISH_READY">可以发布</option></select><select id="kind"><option value="">全部类型</option><option value="candidate">地点候选</option><option value="mention">地点提及</option><option value="poi">正式地点</option><option value="knowledge_candidate">知识候选</option><option value="knowledge_draft">知识草稿</option><option value="event_candidate">活动候选</option><option value="event">活动</option><option value="official_guidance_snapshot">官方指引</option><option value="source_discovery_candidate">来源发现</option><option value="source_content">来源内容</option><option value="raw_source_record">Raw 记录</option><option value="source_run">来源运行</option><option value="processing_state">处理状态</option><option value="content_classification">本地分类结果</option></select><button class="secondary" id="refresh">刷新</button></div><div id="count" class="count"></div><div class="tablewrap"><table><thead><tr><th scope="col">选择</th><th scope="col">类型</th><th scope="col">内容</th><th scope="col">状态</th><th scope="col">城市</th><th scope="col">更新时间</th></tr></thead><tbody id="items"></tbody></table></div></div><aside id="detail"><div class="detail-empty"><b>选择一条内容查看证据</b><p>这里会显示来源、系统判断、审核历史和可执行动作。</p></div></aside></div></section>

<section id="publish" class="panel"><h2>4. 准备并发布到 LAND</h2><p class="lead">先做只读预检，再按“准备 → 查看差异 → 验证 → 安装”操作。官方结构化地点可以直接生成发布包，不用填写双语文案。</p><div class="callout"><b>发布边界</b><br>官方地点满足全部门槛时由规则自动通过；社区经验可以由 Codex 审核。知识内容进入 QAU；Event 和官方 Guide 目前不会进入 LAND 发布包。</div><div id="publish-storage-note" class="callout" style="margin-top:10px"><b>当前 Dashboard 数据库</b><br><span>正在读取路径……</span></div><div class="publish-grid" style="margin-top:14px"><div class="field"><label for="pub-content-type">要发布哪类内容？</label><select id="pub-content-type"><option value="knowledge">知识内容（QAU）</option><option value="place">地点内容（Place）</option></select><span id="pub-kind-help" class="hint">适合文化、礼仪和实用知识。使用现有 QAU 发布流程。</span></div><div class="field"><label for="pub-city">城市 ID</label><input id="pub-city" placeholder="例如 new-york"><span class="hint">准备新包或预检时填写；查看已有包时可留空。</span></div><div class="field"><label for="pub-release">发布包 ID</label><input id="pub-release" placeholder="准备后自动填入"><span class="hint">差异、验证、安装和回滚都使用这个 ID。</span></div><div class="field"><label for="pub-reviewer">操作者</label><input id="pub-reviewer" placeholder="安装或人工文案审核时填写"><span class="hint">官方自动发布的预检、准备和验证可以留空；安装仍需记录操作者。</span></div><div class="field"><label for="pub-reason">操作原因</label><input id="pub-reason" placeholder="例如：安装已验证的地点包"></div><div id="pub-place-fields" class="field-grid" style="grid-column:1/-1;display:none"><div class="field"><label for="pub-poi-ids">要发布的 POI ID</label><textarea id="pub-poi-ids" placeholder="每行一个，或用逗号分隔"></textarea><span class="hint">系统不会自动选择全城地点。请从正式地点列表复制需要发布的稳定 ID。</span></div><div class="field"><label for="pub-overlay-path">可选：人工文案文件</label><input id="pub-overlay-path" placeholder="官方数据通常留空"><span class="hint">只有你希望覆盖自动生成的来源说明时才填写。社区内容发布仍需要已审核的文案。</span></div><p class="hint" style="grid-column:1/-1;margin:0">预检会逐条检查坐标、来源、审核状态和字段完整性。显示 <b>deterministic_official</b> 时可以直接准备；出现 blocker 时交给 Codex 或补充证据。</p></div></div><div class="actions"><button id="publish-preflight" class="secondary" disabled>0. 只读预检</button><button id="publish-prepare">1. 准备发布包</button><button id="publish-diff" class="secondary">2. 查看差异</button><button id="publish-verify" class="secondary">3. 验证发布包</button><button id="install" class="danger" disabled>4. 安装到 LAND</button><button id="publish-rollback" class="secondary">回滚已安装包</button></div><div id="pub-result" class="result"></div><p class="footer-note">只有启动 Dashboard 时显式加入 <code>--allow-install</code>，并且当前包已验证通过，安装和回滚才会执行。浏览器刷新后仍需重新验证，避免误操作。</p></section>
<section id="pub-place-extra" class="panel" style="display:none"><h3>可选：覆盖自动生成的 Place 文案</h3><p class="lead">官方结构化地点可以把这里留空。需要编辑社区经验或品牌文案时，再粘贴人工整理的 JSON；不要复制作者身份、原帖全文或卫生等级。</p><div class="field"><label for="pub-overlay-json">可选 publication overlay JSON</label><textarea id="pub-overlay-json" rows="14" placeholder="通常留空；需要自定义时再生成模板"></textarea></div><div class="actions"><button type="button" id="pub-template" class="secondary small">生成高级填写模板</button></div><details><summary>查看双语高级示例</summary><pre class="pre">{"city":"new-york","destination":{"zh-Hans":{"name":"纽约","localName":"纽约","summary":"已核对的地点"},"en":{"name":"New York","localName":"New York","summary":"Reviewed places"}},"places":{"poi-1":{"zh-Hans":{"name":"中文名","localName":"English name","address":"地址","reason":"人工整理的理由","caution":"人工整理的注意事项"},"en":{"name":"English name","localName":"English name","address":"Address","reason":"Editorial reason","caution":"Editorial caution"}}}}</pre></details></section>
</main>
<script>const csrf=__CSRF__;let selected=null;const llmSelected=new Set();const llmSelectedCities=new Map();let lastItems=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stepInfo={xhs_collect:{title:'从小红书采集新内容',body:'使用已登录的本机浏览器按城市搜索词采集可见帖子。登录失效时会打开登录窗口。',tags:['需要登录','零 LLM'],out:'输出：Raw、SourceContent 和采集状态'},threads_collect:{title:'从 Threads 搜集公开帖子',body:'使用 Meta 官方 Threads API 按关键词搜索公开帖子。需要预先配置 OAuth token；关键词结果仍要核对城市。',tags:['需要官方 OAuth','零 LLM','最多 5 篇'],out:'输出：Raw、SourceContent、地点候选和审核状态'},xhs_process:{title:'整理已采集内容',body:'用规则去重、分类，并把地点、文化礼仪和待模型内容分流。适合首次运行。',tags:['推荐先选','零 LLM'],out:'输出：候选、处理状态和待审核项目'},multi_collect:{title:'运行官方 / OSM 结构化来源',body:'运行这个城市已经配置的官方数据与 OSM 来源；未配置来源会明确报错。',tags:['无需登录','零 LLM'],out:'输出：结构化 POI、活动或来源运行记录'},land_raw_process:{title:'处理 LAND Raw 文件',body:'读取 LAND/Raw 目录中的历史 JSON，走确定性处理链。',tags:['本地文件','零 LLM'],out:'输出：Raw、SourceContent 和候选'},publish_prepare:{title:'准备知识发布包',body:'把已人工接受的知识冻结成候选发布包，不会自动安装。',tags:['需要已审核内容','零 LLM'],out:'输出：release、diff 和 blocker'},knowledge_extract:{title:'用千问整理选中的候选',body:'推荐回到第 3 步勾选“知识候选”，再启动模型辅助审核；结果仍需人工审核。',tags:['会调用千问','仅选中内容'],out:'输出：DRAFT_NEEDS_REVIEW 草稿，不会自动发布'}};
function dismissWelcome(){document.getElementById('welcome').classList.add('hidden');try{localStorage.setItem('land-dashboard-welcome','done')}catch(_){} }
function explainStep(){const step=document.getElementById('wf-step').value,x=stepInfo[step];document.getElementById('job-explain').innerHTML=`<b>${esc(x.title)}</b><span>${esc(x.body)}</span><div class="facts">${x.tags.map(t=>`<span class="tag ${t.includes('LLM')&&!t.includes('零')?'llm':'zero'}">${esc(t)}</span>`).join('')}</div><p class="hint">${esc(x.out)}</p>`;document.getElementById('threads-fields').style.display=step==='threads_collect'?'grid':'none'}
function humanError(message){const m=String(message||'操作失败');let recovery='请检查填写内容后重试。';if(/auth|login|登录/i.test(m))recovery='请在打开的浏览器完成登录，然后重新启动同一作业。';else if(/source|scope|配置|unknown city/i.test(m))recovery='先查看采集计划，补齐城市或来源配置后重试。';else if(/review|blocker|审核/i.test(m))recovery='回到人工审核列表，处理阻塞项后重新准备发布包。';else if(/network|timeout|DNS|连接/i.test(m))recovery='已有数据不会丢失；网络恢复后重新启动同一作业。';return `<div class="callout error"><b>${esc(m)}</b><br>${esc(recovery)}</div>`}
async function api(url,options){try{const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw new Error(d.error||`请求失败 (${r.status})`);return d}catch(e){throw new Error(e.message||'无法连接 Dashboard') }}
async function load(){const p=new URLSearchParams();if(q.value)p.set('q',q.value);if(bucket.value)p.set('bucket',bucket.value);if(kind.value)p.set('kind',kind.value);try{const d=await api('/api/items?'+p);lastItems=d.items||[];lastItems.forEach(x=>{if(!(x.payload&&x.payload.llm_eligible)){llmSelected.delete(x.id);llmSelectedCities.delete(x.id)}});count.textContent=`共 ${d.total} 条 · 当前 ${d.shown} 条 · 需要审核 ${d.counts.REVIEW_REQUIRED||0} 条`;items.innerHTML=lastItems.map(x=>{const eligible=Boolean(x.payload&&x.payload.llm_eligible);const reason=(x.payload&&x.payload.llm_disabled_reason)||'此类记录不支持知识候选模型整理';const choice=eligible?`<input class="llm-check" type="checkbox" data-llm-id="${esc(x.id)}" aria-label="选择 ${esc(x.label)} 交给模型整理" ${llmSelected.has(x.id)?'checked':''} onchange="toggleLLMFromRow(this);event.stopPropagation()">`:`<span class="disabled-choice" title="${esc(reason)}" aria-label="${esc(reason)}">不可选</span>`;return `<tr class="item" tabindex="0" onclick="showItem('${esc(x.kind)}','${esc(x.id)}')" onkeydown="if(event.key==='Enter')showItem('${esc(x.kind)}','${esc(x.id)}')"><td class="check-cell" onclick="event.stopPropagation()">${choice}</td><td>${esc(kindName(x.kind))}<br><span class="pill">${esc(x.bucket)}</span></td><td><b>${esc(x.label)}</b><br><span class="hint">${esc(x.summary).slice(0,120)}</span></td><td>${esc(x.status_label)}</td><td>${esc(x.city)}</td><td>${esc(x.updated_at)}</td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty"><b>没有匹配内容</b><br>清除搜索或切换到“全部状态”再看看。</div></td></tr>';updateLLMBudget()}catch(e){items.innerHTML=`<tr><td colspan="6">${humanError(e.message)}</td></tr>`}}
function kindName(k){return ({candidate:'地点候选',mention:'地点提及',poi:'正式地点',knowledge_candidate:'知识候选',knowledge_draft:'知识草稿',event_candidate:'活动候选',event:'活动',official_guidance_snapshot:'官方指引',source_discovery_candidate:'来源候选',source_content:'来源内容',raw_source_record:'Raw 记录',source_run:'来源运行',processing_state:'处理状态'})[k]||k}
function updateLLMBudget(){const total=llmSelected.size;const limit=document.getElementById('review-llm-limit');if(total&&(!limit.dataset.manual||Number(limit.value)<total))limit.value=String(total);const hardLimit=Number(limit.value)||0;const maxCalls=Math.min(total,hardLimit);document.getElementById('llm-budget').textContent=total?`已选 ${total} 条，预计最多调用 ${maxCalls} 次；结果会进入待人工审核，不会自动发布。`:'已选 0 条，预计最多调用 0 次。还没有启动模型作业。';document.getElementById('start-llm-review').disabled=total===0||hardLimit<total}
function toggleLLMFromRow(box){const id=box.dataset.llmId;const item=lastItems.find(x=>x.id===id);const city=document.getElementById('wf-city').value.trim();if(box.checked&&city&&item&&item.city!==city){box.checked=false;document.getElementById('llm-review-message').innerHTML=humanError(`该候选属于 ${item.city||'其他城市'}，当前作业城市是 ${city}；请先切换城市或重新筛选。`);return}if(box.checked){llmSelected.add(id);llmSelectedCities.set(id,item&&item.city||'')}else{llmSelected.delete(id);llmSelectedCities.delete(id)}updateLLMBudget()}
function selectLLMFirst(){const raw=Number(document.getElementById('llm-pick-count').value);const n=Number.isFinite(raw)?Math.max(1,Math.min(100,Math.floor(raw))):1;const city=document.getElementById('wf-city').value.trim();const eligible=lastItems.filter(x=>x.payload&&x.payload.llm_eligible&&(!city||x.city===city));eligible.slice(0,n).forEach(x=>{llmSelected.add(x.id);llmSelectedCities.set(x.id,x.city||'')});updateLLMBudget();document.getElementById('llm-review-message').innerHTML=`<div class="callout success">已选择 ${Math.min(n,eligible.length)} 条。${n>eligible.length?'当前城市和列表中的可选项不足，已全部选择。':'请确认上方“预计最多调用”后再启动。'}</div>`;load()}
function clearLLMSelection(){llmSelected.clear();updateLLMBudget();document.getElementById('llm-review-message').innerHTML='<div class="callout">已清空模型审核选择；当前仍是 0 次 LLM。</div>';load()}
async function startSelectedLLMReview(){const ids=Array.from(llmSelected),city=document.getElementById('wf-city').value.trim(),reviewer=document.getElementById('wf-reviewer').value.trim(),reason=document.getElementById('wf-reason').value.trim(),model=document.getElementById('review-llm-model').value.trim(),limit=Number(document.getElementById('review-llm-limit').value);const foreign=ids.filter(id=>llmSelectedCities.get(id)!==city);if(!ids.length){document.getElementById('llm-review-message').innerHTML=humanError('请先勾选知识候选，或使用“选择当前列表前 N 条”');return}if(!city||!reviewer||!reason){document.getElementById('llm-review-message').innerHTML=humanError('启动模型审核前，请先填写城市、操作者和本次原因');return}if(foreign.length){document.getElementById('llm-review-message').innerHTML=humanError('所选候选中包含其他城市或未确认城市的内容；请清空选择后，在当前城市列表重新选择');return}if(!model||!Number.isInteger(limit)||limit<ids.length||limit>100){document.getElementById('llm-review-message').innerHTML=humanError(`最大调用次数必须是 ${ids.length} 或更高，且不超过 100`);return}document.getElementById('llm-review-message').innerHTML=`<div class="callout">正在提交：${ids.length} 条，预计最多调用 ${Math.min(ids.length,limit)} 次。结果只会生成待人工审核草稿。</div>`;try{const d=await api('/api/workflow',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({operation:'start_job',confirm:'START_JOB',city,reviewer,reason,step:'knowledge_extract',candidate_ids:ids,model,llm_limit:limit,llm_opt_in:true})});const plan=d.llm_plan||{};document.getElementById('llm-review-message').innerHTML=`<div class="callout success"><b>模型审核作业已启动</b><br>预计最多调用 ${plan.max_calls||Math.min(ids.length,limit)} 次；作业完成后请在列表查看 DRAFT_NEEDS_REVIEW 并人工决定。</div>`;document.getElementById('wf-result').textContent=JSON.stringify(d,null,2);await loadWorkflow()}catch(e){document.getElementById('llm-review-message').innerHTML=humanError(e.message)}}
async function showItem(k,id){selected={kind:k,id};try{const d=await api('/api/item?'+new URLSearchParams({kind:k,id}));detail.innerHTML=`<div class="detail-section"><h3>${esc(kindName(k))}</h3><span class="tag">${esc(d.status_label||d.status||'详情')}</span></div><div class="detail-section"><h4>证据与系统记录</h4><pre class="pre">${esc(JSON.stringify(d,null,2))}</pre></div>${actionForm(d)}`}catch(e){detail.innerHTML=humanError(e.message)}}
function actionForm(d){if(d.read_only)return '<div class="detail-section"><b>当前只需查看</b><p class="hint">这种记录用于解释采集和处理过程，没有人工决策按钮。</p></div>';const k=selected.kind;if(k==='knowledge_draft'&&d.status==='DRAFT_NEEDS_REVIEW')return `<div class="detail-section"><h4>你的决定</h4><div class="field-grid"><div class="field"><label>审核人<input id="reviewer"></label></div><div class="field"><label>原因<input id="reason"></label></div><div class="field"><label>官方 / 运营方 URL<input id="reference_url"></label></div><div class="field"><label>来源类型<select id="reference_kind"><option value="">个人经验</option><option value="official">官方</option><option value="operator">运营方</option></select></label></div><div class="field"><label>来源标题<input id="reference_title"></label></div><div class="field"><label>验证时间<input id="verified_at" placeholder="2026-09-26T00:00:00Z"></label></div><div class="field"><label>有效期<input id="valid_until" placeholder="可选"></label></div></div><div class="actions"><button onclick="act('approve')">通过</button><button class="danger" onclick="act('reject')">拒绝</button></div></div>`;if(['NEEDS_REVIEW','DISCOVERED'].includes(d.status))return `<div class="detail-section"><h4>你的决定</h4><div class="field"><label>审核人<input id="reviewer"></label></div><div class="field"><label>原因<textarea id="reason"></textarea></label></div>${k==='candidate'?'<div class="field"><label>已有 POI ID（绑定时填写）<input id="poi_id"></label></div>':''}<div class="actions"><button onclick="act('approve')">通过</button>${k==='candidate'?'<button class="secondary" onclick="act(&quot;resolve&quot;)">绑定已有地点</button><button class="secondary" onclick="act(&quot;promote&quot;)">创建新地点</button>':''}<button class="danger" onclick="act('reject')">拒绝</button></div></div>`;return '<div class="detail-section"><p class="hint">当前状态没有需要执行的人工动作。</p></div>'}
async function act(action){const p={kind:selected.kind,id:selected.id,action,reviewer:(document.getElementById('reviewer')||{}).value||'',reason:(document.getElementById('reason')||{}).value||''};for(const id of ['reference_url','reference_kind','reference_title','verified_at','valid_until','poi_id']){const e=document.getElementById(id);if(e)p[id]=e.value}try{const d=await api('/api/action',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(p)});detail.innerHTML=`<div class="callout success"><b>操作已保存</b><pre class="pre">${esc(JSON.stringify(d,null,2))}</pre></div>`;load()}catch(e){detail.insertAdjacentHTML('afterbegin',humanError(e.message))}}
function chooseCommunitySource(step){const select=document.getElementById('wf-step');if(!select||!step)return;select.value=step;explainStep();document.getElementById('wf-message').innerHTML='<div class="callout success"><b>已选择这个平台</b><br>请确认登录状态和搜索词后，再启动采集。</div>';select.scrollIntoView({behavior:'smooth',block:'center'})}
function renderPlan(d){d=d||{};const rows=Array.isArray(d.sources)?d.sources:[];const statusText={READY:'已配置，可以运行',READY_WITH_LOGIN:'已配置，需要浏览器登录',TERMINAL_ONLY:'已配置，可从终端运行',CONFIGURED_BUT_UNAVAILABLE:'已配置，尚未接入 Dashboard',UNCONFIGURED_FOR_CITY:'这个城市尚未配置',SCOPE_MISSING:'缺少采集范围文件',CITY_OR_QUERY_MISSING:'请先创建城市和搜索词'};document.getElementById('wf-plan').innerHTML=rows.map(s=>{const login=s.requires_login?'需要登录':'无需登录';const model=s.requires_llm?'需要模型':'零 LLM';const community=s.source_type==='community';const search=s.supports_auto_search?'Dashboard 可自动搜索':(s.supports_search?'支持搜索，但当前不能从 Dashboard 自动启动':'不支持自动搜索');const auth=s.auth_status==='oauth_token_missing'?'OAuth token 未配置':(s.auth_status==='oauth_token_configured'?'OAuth token 已配置':'');const action=s.dashboard_selectable&&s.workflow_step?`<button class="secondary small" type="button" onclick="chooseCommunitySource('${esc(s.workflow_step)}')">选择此平台</button>`:'';return `<article class="source ${community?'community-source':''}"><h4>${esc(s.display_name||s.source||'未命名来源')}</h4><span class="status ${esc(s.status||'')}">${esc(statusText[s.status]||s.status||'状态未知')}</span><p>${esc(s.kind||'source')} · ${esc(login)} · ${esc(model)}</p>${community?`<p>${esc(search)}${auth?' · '+esc(auth):''}</p>`:''}${s.notes?`<p>${esc(s.notes)}</p>`:''}${s.entrypoint?`<p class="path">入口：${esc(s.entrypoint)}</p>`:''}${s.query_file?`<p class="path">搜索词：${esc(s.query_file)}</p>`:''}${s.scope?`<p class="path">范围：${esc(s.scope)}</p>`:''}${s.storage?`<p class="path">保存：${esc(Object.values(s.storage).join(' · '))}</p>`:''}${action?`<div class="actions">${action}</div>`:''}</article>`}).join('')||'<div class="empty">这个城市还没有可显示的来源。</div>';document.getElementById('wf-plan-raw').textContent=JSON.stringify(d,null,2);document.getElementById('wf-message').innerHTML=`<div class="callout ${d.city_exists?'success':''}"><b>${d.city_exists?'城市已经建立':'城市还没有建立'}</b><br>${d.city_exists?'可以从已配置的来源开始采集。':'先填写城市名称和国家代码，再点击“创建 / 补全城市”。'}</div>`}
function renderHomepage(h){const box=document.getElementById('homepage-action');if(!box)return;h=h||{};if(!h.city){box.innerHTML='';return}const policy=h.codex_policy||{};if(h.status==='PRESENT'&&h.ready){box.innerHTML=`<div class="callout success"><b>LAND 已有可用的城市主页</b><br>主页注册状态为 ready；${h.published_content_present?'城市内容包也已存在。':'当前还没有该城市的数据内容包，可以继续采集。'}</div>`;return}if(h.status==='PREVIEW_NEEDS_ACCEPTANCE'){box.innerHTML=`<div class="callout homepage-card"><b>LAND 已有城市主页预览，但还需要验收</b><br>当前 registry 状态是 scaffold / NEEDS_ACCEPTANCE。先验收主页并把 reviewState 改为 ready，再发布城市数据。<p class="task-path">${esc(h.city_home_registry_path||'')}</p><p class="hint">这不是缺少主页，所以不会重复创建生成任务。</p></div>`;return}const active=h.active_task;if(active){const p=active.codex||{};const e=active.execution||{};box.innerHTML=`<div class="callout homepage-card"><b>Codex 主页作业：${esc(active.status)}</b><br>模型 ${esc(p.model||e.model||policy.model||'gpt-5.6-sol')} · 强度 ${esc(p.reasoning_effort||e.reasoning_effort||policy.reasoning_effort||'high')} · 最多 ${esc(p.max_calls||e.max_calls||policy.max_calls||1)} 次；Qwen 0 次。<br>${active.status==='TASK_READY'?'任务已就绪，尚未运行 Codex。':'Codex 正在运行，完成后会重新检查 LAND registry。'}<p class="task-path">${esc(active.task_path||'')}</p><details><summary>查看任务状态和执行参数</summary><pre class="pre">${esc(JSON.stringify(active,null,2))}</pre></details></div>`;return}box.innerHTML='<div class="callout homepage-card"><b>LAND 里还没有这个城市主页</b><br>确定让 Codex 生成一个吗？确认后会创建并尝试启动受限的本地 Codex 作业；如果本机不可执行，任务会保留为 TASK_READY，不会伪装已经生成。<div class="actions"><button id="request-homepage" type="button">确定，让 Codex 生成主页</button></div><p class="hint">检测文件 LAND/Resources/city-home-registry.json；固定模型 gpt-5.6-sol · high 强度 · workspace-write · 最多 1 次 Codex 作业 · Qwen 0 次。任务会要求保持 LAND 现有风格、使用当地特色大字、加入一个当地文化动态元素，并支持减少动效；数据采集完成后再通过发布桥接导入。</p></div>';document.getElementById('request-homepage').addEventListener('click',requestHomepage)}
async function requestHomepage(){const city=document.getElementById('wf-city').value.trim(),reviewer=document.getElementById('wf-reviewer').value.trim(),reason=document.getElementById('wf-reason').value.trim();if(!city||!reviewer||!reason){document.getElementById('wf-message').innerHTML=humanError('确认生成主页前，请先填写城市、操作者和本次原因');return}const button=document.getElementById('request-homepage');if(button)button.disabled=true;try{const d=await api('/api/workflow',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({operation:'request_homepage',confirm:'REQUEST_HOMEPAGE',city,reviewer,reason})});const p=d.homepage&&d.homepage.codex_policy||{};document.getElementById('wf-message').innerHTML=`<div class="callout success"><b>Codex 主页作业已提交</b><br>状态是 ${esc(d.status||'TASK_READY')}；模型 ${esc(p.model||'gpt-5.6-sol')} · 强度 ${esc(p.reasoning_effort||'high')} · Qwen 0 次。完成前不会把主页标为 ready。</div>`;renderHomepage(d.homepage);await loadWorkflow()}catch(e){if(button)button.disabled=false;document.getElementById('wf-message').innerHTML=humanError(e.message)}}
async function loadPlan(){const city=document.getElementById('wf-city').value.trim();if(!city){document.getElementById('wf-message').innerHTML=humanError('请先填写城市 ID');return}try{const d=await api('/api/workflow/plan?'+new URLSearchParams({city}));renderPlan(d);renderHomepage(d.homepage)}catch(e){document.getElementById('wf-message').innerHTML=humanError(e.message)}}
async function workflow(operation){const city=document.getElementById('wf-city').value.trim(),reviewer=document.getElementById('wf-reviewer').value.trim(),reason=document.getElementById('wf-reason').value.trim();let p={operation,city,reviewer,reason,confirm:operation==='create_city'?'CREATE_CITY':'START_JOB'};if(operation==='create_city'){p.city_name=document.getElementById('wf-city-name').value.trim();p.country=document.getElementById('wf-country').value.trim()}else{p.step=document.getElementById('wf-step').value;p.params={};const sources=document.getElementById('wf-sources').value.split(',').map(x=>x.trim()).filter(Boolean);if(p.step==='multi_collect'&&sources.length)p.params.only_sources=sources;if(p.step==='threads_collect'){p.params.query=document.getElementById('wf-threads-query').value.trim();p.params.search_type=document.getElementById('wf-threads-search-type').value;p.params.limit=Number(document.getElementById('wf-threads-limit').value);p.params.pages=1;p.params.timeout=15}if(p.step==='knowledge_extract'){p.candidate_ids=document.getElementById('wf-candidates').value;p.model=document.getElementById('wf-model').value;p.llm_limit=document.getElementById('wf-limit').value;p.llm_opt_in=true}}try{const d=await api('/api/workflow',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(p)});document.getElementById('wf-message').innerHTML=`<div class="callout success"><b>${operation==='create_city'?'城市已准备好':'作业已启动'}</b><br>可以在进度区继续查看。</div>`;document.getElementById('wf-result').innerHTML='';await loadPlan();await loadWorkflow()}catch(e){document.getElementById('wf-result').innerHTML=humanError(e.message)}}
function recovery(j){if(j.status==='AUTH_REQUIRED')return j.step==='threads_collect'?'先完成 Meta 官方 OAuth，并让 Dashboard 进程读取 LAND_THREADS_ACCESS_TOKEN，再重试。':'完成浏览器登录后，重新启动同一作业。';if(j.status==='FAILED')return '查看错误；修复网络或配置后重新启动，已有数据不会丢失。';if(j.status==='INTERRUPTED')return 'Dashboard 曾重启；重新启动同一作业即可。';if(j.status==='SUCCEEDED_WITH_REVIEW')return '采集完成，但有内容需要去审核列表处理。';if(j.status==='SUCCEEDED')return '已完成。下一步去审核列表查看新增或变化内容。';return ''}
async function cancelJob(id){const p={operation:'cancel_job',job_id:id,reviewer:document.getElementById('wf-reviewer').value,reason:document.getElementById('wf-reason').value,confirm:'CANCEL_JOB'};try{await api('/api/workflow',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(p)});loadWorkflow()}catch(e){document.getElementById('wf-result').innerHTML=humanError(e.message)}}
async function loadWorkflow(){const city=document.getElementById('wf-city').value.trim();try{const homepagePromise=city?api('/api/workflow/homepage?'+new URLSearchParams({city})):Promise.resolve(null);const [a,b,c,h]=await Promise.all([api('/api/workflow/cities'),api('/api/workflow/jobs?'+new URLSearchParams(city?{city}:{})),api('/api/workflow/storage?'+new URLSearchParams(city?{city}:{})),homepagePromise]);if(h)renderHomepage(h);const jobs=b.jobs||[];document.getElementById('wf-jobs').innerHTML=jobs.map(j=>`<article class="job"><h4>${esc((stepInfo[j.step]||{}).title||j.step)}</h4><span class="status ${esc(j.status)}">${esc(j.status)}</span><div class="progress"><span style="width:${Math.round((j.progress||0)*100)}%"></span></div><p>${Math.round((j.progress||0)*100)}% · LLM ${esc(j.llm_calls||0)}/${esc(j.llm_limit||0)}</p>${j.error?`<p class="status FAILED">${esc(j.error)}</p>`:''}<p>${esc(recovery(j))}</p>${['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(j.status)?`<button class="danger small" onclick="cancelJob('${esc(j.id)}')">取消作业</button>`:''}</article>`).join('')||'<div class="empty">还没有作业。选择一个步骤并点击“启动”。</div>';const locations=(c.locations||{});document.getElementById('storage').innerHTML=Object.entries(locations).map(([k,v])=>`<article class="storage"><h4>${esc(({database:'主数据库',xiaohongshu_capture_dir:'小红书采集文件',land_raw_dir:'LAND Raw',release_dir:'发布包',dashboard_job_log_dir:'作业日志',city_config:'城市配置',source_config:'来源配置',multi_source_config:'多来源配置',project_root:'项目目录',xiaohongshu_query_config:'城市搜索词'})[k]||k)}</h4><p class="path">${esc(v)}</p><span class="tag">${c.exists&&c.exists[k]?'已存在':'尚未创建'}</span></article>`).join('');const dbPath=locations.database||'当前数据库路径不可用';document.getElementById('publish-storage-note').innerHTML=`<b>当前 Dashboard 数据库</b><br><span class="path">${esc(dbPath)}</span><br><span class="hint">审核、预检和采集进度都读取这个数据库。</span>`;document.getElementById('runtime').textContent=JSON.stringify({cities:a,jobs:b,storage:c,homepage:h},null,2)}catch(e){document.getElementById('wf-result').innerHTML=humanError(e.message)}}
function updatePublishMode(){const place=document.getElementById('pub-content-type').value==='place';document.getElementById('pub-place-fields').style.display=place?'grid':'none';document.getElementById('pub-place-extra').style.display=place?'block':'none';document.getElementById('pub-kind-help').textContent=place?'官方结构化 restaurant、cafe、museum 满足门槛时可零人工发布；其他来源先由 Codex 或人工审核。':'适合文化、礼仪和实用知识。使用现有 QAU 发布流程。';document.getElementById('publish-preflight').disabled=!place;document.getElementById('install').disabled=true}
function placeIds(){return document.getElementById('pub-poi-ids').value.split(/[\n,]/).map(x=>x.trim()).filter(Boolean)}
function generatePlaceTemplate(){const city=document.getElementById('pub-city').value.trim()||'city-id';const ids=placeIds();const places={};ids.forEach(id=>{places[id]={"zh-Hans":{"name":"","localName":"","address":"","reason":"","caution":""},en:{"name":"","localName":"","address":"","reason":"","caution":""}}});document.getElementById('pub-overlay-json').value=JSON.stringify({city,destination:{"zh-Hans":{"name":"","localName":"","summary":""},en:{"name":"","localName":"","summary":""}},places},null,2)}
function publishPayload(operation){const place=document.getElementById('pub-content-type').value==='place';const p={operation,content_type:place?'place':'knowledge',reviewer:document.getElementById('pub-reviewer').value,reason:document.getElementById('pub-reason').value,confirm:operation.toUpperCase(),city:document.getElementById('pub-city').value,release:document.getElementById('pub-release').value};if(place){p.poi_ids=document.getElementById('pub-poi-ids').value;const inline=document.getElementById('pub-overlay-json').value.trim();if(inline){try{p.publication_overlay=JSON.parse(inline)}catch(_){throw new Error('可选 Place 文案 JSON 格式不正确，请检查大括号和引号')}}else{p.overlay_path=document.getElementById('pub-overlay-path').value}}return p}
function preflightBlockerText(blocker){const labels={OVERLAY_MISSING:'该来源不符合官方自动发布条件，需要 Codex / 人工审核并提供发布文案',OVERLAY_INVALID:'可选 publication overlay 不是有效的 JSON 对象',CITY_MISMATCH:'城市与当前发布城市不一致',POI_NOT_FOUND:'找不到这个 POI',UNKNOWN_CATEGORY:'地点类型暂不支持 LAND Place',UNSAFE_POI_STATUS:'POI 的坐标、激活或验证门槛未满足',REVIEW_STATUS_UNSAFE:'POI 当前状态不是 AUTO_APPROVED',LAST_VERIFIED_AT_MISSING:'缺少带时区的最近核验时间',PROVENANCE_MISSING:'缺少 POI 字段来源记录',STABLE_HTTPS_SOURCE_MISSING:'缺少稳定的 HTTPS 来源',REVIEW_DECISION_MISSING:'缺少冻结的 AUTO_APPROVED ReviewDecision',DESTINATION_OVERLAY_MISSING:'该来源需要城市发布文案',PLACE_OVERLAY_MISSING:'该来源需要地点发布文案',DESTINATION_TRANSLATION_MISSING:'人工文案缺少一种语言',DESTINATION_FIELD_MISSING:'城市文案有空字段',PLACE_TRANSLATION_MISSING:'地点文案缺少一种语言',PLACE_FIELD_MISSING:'地点文案有空字段',HEALTH_GRADE_IN_PUBLICATION_COPY:'reason/caution 不能写卫生等级',OVERLAY_POI_NOT_SELECTED:'文案包含未选择的 POI'};return labels[blocker.code]||blocker.message||'需要处理'}
function preflightDetails(d){if(!Array.isArray(d.items))return '';const mode=d.approval_mode==='deterministic_official'?'规则自动通过，无需逐条人工审核':d.approval_mode==='human_reviewed'?'已审核内容':'仍需处理';const copy=d.overlay_mode==='deterministic_fallback'?'使用来源语言和保守来源说明，不要求填写双语':'使用人工提供的发布文案';const rows=d.items.map(item=>{const blockers=item.blockers||[];const body=blockers.length?blockers.map(b=>`<div class="blocker"><b>${esc(b.code||'BLOCKED')}</b> · ${esc(preflightBlockerText(b))}</div>`).join(''):'<div class="hint">没有 blocker，可以进入准备发布包。</div>';return `<article class="preflight-item ${item.ready?'ready':'blocked'}"><b>${esc(item.poi_id)} · ${item.ready?'READY，可以进入下一步':'BLOCKED，需要处理'}</b>${body}</article>`}).join('');return `<div class="preflight-list"><div class="callout ${d.status==='READY'?'success':'error'}"><b>${esc(mode)}</b><br>${esc(copy)}</div><h4>每个 POI 的预检结果</h4>${rows}</div>`}
async function publish(operation){try{const p=publishPayload(operation);const d=await api('/api/publish',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(p)});const failed=d.ok===false||['BLOCKED','DRIFTED','INSTALL_FAILED_ROLLED_BACK','ROLLBACK_FAILED_RESTORED'].includes(d.status);const title=operation==='preflight'?(failed?'预检发现需要处理的 blocker':'预检完成'):(failed?'需要处理 blocker 或错误':'操作完成');const details=operation==='preflight'?preflightDetails(d):'';const raw=operation==='preflight'?`<details class="raw-toggle"><summary>查看预检原始 JSON</summary><pre class="pre">${esc(JSON.stringify(d,null,2))}</pre></details>`:`<pre class="pre">${esc(JSON.stringify(d,null,2))}</pre>`;document.getElementById('pub-result').innerHTML=`<div class="callout ${failed?'error':'success'}"><b>${title}</b>${details}${raw}</div>`;if(d.release_id)document.getElementById('pub-release').value=d.release_id;if(operation==='verify')document.getElementById('install').disabled=!(d.ok&&d.allow_install)}catch(e){document.getElementById('pub-result').innerHTML=humanError(e.message)}}
document.getElementById('dismiss-welcome').addEventListener('click',dismissWelcome);document.getElementById('create-city').addEventListener('click',()=>workflow('create_city'));document.getElementById('load-plan').addEventListener('click',loadPlan);document.getElementById('wf-step').addEventListener('change',explainStep);document.getElementById('start-job').addEventListener('click',()=>workflow('start_job'));document.getElementById('refresh-workflow').addEventListener('click',loadWorkflow);document.getElementById('pub-content-type').addEventListener('change',updatePublishMode);document.getElementById('pub-template').addEventListener('click',generatePlaceTemplate);document.getElementById('publish-preflight').addEventListener('click',()=>publish('preflight'));document.getElementById('publish-prepare').addEventListener('click',()=>publish('prepare'));document.getElementById('publish-diff').addEventListener('click',()=>publish('diff'));document.getElementById('publish-verify').addEventListener('click',()=>publish('verify'));document.getElementById('install').addEventListener('click',()=>publish('install'));document.getElementById('publish-rollback').addEventListener('click',()=>publish('rollback'));document.getElementById('llm-select-first').addEventListener('click',selectLLMFirst);document.getElementById('llm-clear-selection').addEventListener('click',clearLLMSelection);document.getElementById('start-llm-review').addEventListener('click',startSelectedLLMReview);document.getElementById('review-llm-limit').addEventListener('input',()=>{document.getElementById('review-llm-limit').dataset.manual='1';updateLLMBudget()});refresh.addEventListener('click',load);q.addEventListener('change',load);bucket.addEventListener('change',load);kind.addEventListener('change',load);try{if(localStorage.getItem('land-dashboard-welcome')==='done')document.getElementById('welcome').classList.add('hidden')}catch(_){}updatePublishMode();explainStep();updateLLMBudget();load();loadWorkflow();setInterval(loadWorkflow,5000);
</script></body></html>'''
    return page.replace("__CSRF__", json.dumps(csrf)).encode("utf-8")


